            if (authService == null) {
                updateStatus("Error: Servicio de autenticación no disponible", "error");
                LOGGER.log(Level.SEVERE, "AuthService es null en LoginController");
                return;
            }

            String token = authService.login(email, password);

            // Guardar token en AppState
            appState.setAuthToken(token);
            appState.setCurrentUserEmail(email);

            // Mostrar éxito
            updateStatus("✓ Login exitoso. Bienvenido, " + email, "success");
            LOGGER.log(Level.INFO, "Login exitoso para: " + email);

            // Limpiar campos
            emailField.clear();
            passwordField.clear();

            // Navegar a la pantalla de juego
            navigateToGame(email);

        } catch (Exception e) {
            updateStatus("✗ Error de login: " + e.getMessage(), "error");
            LOGGER.log(Level.WARNING, "Error en login: " + e.getMessage());
        }
    }

    /**
     * Navega a la pantalla de juego después del login exitoso.
     *
     * @param playerName nombre del jugador autenticado
     */
    private void navigateToGame(String playerName) {
        try {
            FXMLLoader gameLoader = new FXMLLoader(getClass().getResource("/fxml/Game.fxml"));
            Parent gameRoot = gameLoader.load();

            GameController gameController = gameLoader.getController();
            gameController.setPlayerNames(playerName, "Oponente");
            gameController.setInitialScores(0, 0);

            Scene scene = emailField.getScene();
            scene.setRoot(gameRoot);
            javafx.stage.Stage stage = (javafx.stage.Stage) scene.getWindow();
            stage.setTitle("InazumaGo - Partida");

            LOGGER.log(Level.INFO, "Navegado a pantalla de juego para: " + playerName);
        } catch (Exception e) {
            updateStatus("✗ Error al cargar pantalla de juego: " + e.getMessage(), "error");
            LOGGER.log(Level.SEVERE, "Error al cargar Game.fxml: " + e.getMessage());
        }
    }

    /**
     * Manejador del botón "Limpiar" (opcional).
     */
    @FXML
    public void onClearClicked() {
        emailField.clear();
        passwordField.clear();
        statusLabel.setText("");
        LOGGER.log(Level.INFO, "Campos limpiados");
    }

    /**
     * Actualiza el label de estado con mensaje y color.
     * 
     * @param message mensaje a mostrar
     * @param type tipo de mensaje: "success" (verde) o "error" (rojo)
     */
    private void updateStatus(String message, String type) {
        statusLabel.setText(message);

        if ("success".equals(type)) {
            statusLabel.setTextFill(Color.GREEN);
            LOGGER.log(Level.INFO, "Mensaje de éxito: " + message);
        } else if ("error".equals(type)) {
            statusLabel.setTextFill(Color.RED);
            LOGGER.log(Level.INFO, "Mensaje de error: " + message);
        } else {
            statusLabel.setTextFill(Color.BLACK);
        }
    }
}

package es.iesquevedo.repository.firebase;

import es.iesquevedo.service.auth.AuthService;

import java.io.IOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;

/**
 * Cliente HTTP minimo para llamadas a Firebase RTDB.
 */
public class FirebaseHttpClient {
    private final String baseUrl;
    private final HttpClient httpClient;
    private final AuthService authService;

    public FirebaseHttpClient(String baseUrl, HttpClient httpClient, AuthService authService) {
        this.baseUrl = baseUrl;
        this.httpClient = httpClient;
        this.authService = authService;
    }

    public HttpResponse<String> get(String path) throws IOException, InterruptedException {
        HttpRequest.Builder builder = HttpRequest.newBuilder()
                .uri(URI.create(baseUrl + path))
                .GET();

        authService.getToken().ifPresent(token -> builder.header("Authorization", "Bearer " + token));

        return httpClient.send(builder.build(), HttpResponse.BodyHandlers.ofString());
    }
}

package es.iesquevedo.repository.firebase;

import es.iesquevedo.service.auth.AuthService;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.net.URL;
import java.net.URLConnection;

/**
 * Cliente HTTP minimo para llamadas a Firebase RTDB.
 */
public class FirebaseHttpClient {
    private final String baseUrl;
    private final AuthService authService;

    public FirebaseHttpClient(String baseUrl, AuthService authService) {
        this.baseUrl = baseUrl;
        this.authService = authService;
    }

    public HttpResponse<String> get(String path) throws IOException {
        URL url = new URL(baseUrl + path);
        URLConnection connection = url.openConnection();
        
        if (authService.getToken().isPresent()) {
            connection.setRequestProperty("Authorization", "Bearer " + authService.getToken().get());
        }

        BufferedReader reader = new BufferedReader(new InputStreamReader(connection.getInputStream()));
        StringBuilder response = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            response.append(line);
        }
        reader.close();

        return new HttpResponse<>(response.toString());
    }

    /**
     * Clase simple para encapsular respuesta HTTP
     */
    public static class HttpResponse<T> {
        private final T body;

        public HttpResponse(T body) {
            this.body = body;
        }

        public T body() {
            return body;
        }
    }
}

package es.iesquevedo.repository.firebase;

import es.iesquevedo.dto.GameDto;
import es.iesquevedo.dto.MoveData;
import es.iesquevedo.dto.MoveDto;
import es.iesquevedo.repository.MainRepository;

import com.google.firebase.database.DatabaseReference;
import com.google.firebase.database.DataSnapshot;
import com.google.firebase.database.DatabaseError;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.database.GenericTypeIndicator;
import com.google.firebase.database.ValueEventListener;

import java.io.IOException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.CountDownLatch;
import java.util.function.Consumer;

public class FirebaseMainRepository implements MainRepository {
    private final FirebaseDatabase database;
    @SuppressWarnings({"FieldCanBeLocal", "CollectionWithoutInitialCapacity", "MismatchedQueryAndUpdateOfCollection"})
    private final Map<String, ValueEventListener> listeners = new HashMap<>();

    public FirebaseMainRepository(String firebaseUrl) {
        this.database = FirebaseDatabase.getInstance(firebaseUrl);
    }

    /** Constructor para tests: permite inyectar un FirebaseDatabase mockeado. */
    public FirebaseMainRepository(FirebaseDatabase database) {
        this.database = database;
    }

    @Override
    public CompletableFuture<GameDto> getGame(String gameId) {
        DatabaseReference ref = database.getReference("games/" + gameId);
        CompletableFuture<GameDto> future = new CompletableFuture<>();
        ref.addListenerForSingleValueEvent(new ValueEventListener() {
            @Override
            public void onDataChange(DataSnapshot snapshot) {
                GameDto game = snapshot.getValue(GameDto.class);
                future.complete(game);
            }

            @Override
            public void onCancelled(DatabaseError error) {
                future.completeExceptionally(new Exception(error.getMessage()));
            }
        });
        return future;
    }

    @Override
    public CompletableFuture<Void> writeMoveMultiPath(String gameId, MoveDto payload) {
        DatabaseReference ref = database.getReference("games/" + gameId);
        Map<String, Object> updates = new HashMap<>();
        updates.put("moves", payload.getMoves());
        updates.put("timestamp", payload.getTimestamp());
        updates.put("gameVersion", payload.getGameVersion());
        CompletableFuture<Void> future = new CompletableFuture<>();
        ref.updateChildren(updates, (error, ref1) -> {
            if (error == null) {
                future.complete(null);
            } else {
                future.completeExceptionally(new Exception(error.getMessage()));
            }
        });
        return future;
    }

    @Override
    public String addMovesListener(String gameId, Consumer<List<MoveData>> listener) {
        DatabaseReference ref = database.getReference("games/" + gameId + "/moves");
        ValueEventListener vel = new ValueEventListener() {
            @Override
            public void onDataChange(DataSnapshot snapshot) {
                GenericTypeIndicator<List<MoveData>> t = new GenericTypeIndicator<>() {
                };
                List<MoveData> moves = snapshot.getValue(t);
                listener.accept(moves);
            }

            @Override
            public void onCancelled(DatabaseError error) {
                // Handle error, perhaps log or notify
            }
        };
        ref.addValueEventListener(vel);
        String id = "listener-" + gameId + "-" + System.currentTimeMillis();
        listeners.put(id, vel);
        return id;
    }

    @Override
    public String findDefaultName() {
        DatabaseReference ref = database.getReference("config/defaultName");
        final String[] result = new String[1];
        CountDownLatch latch = new CountDownLatch(1);
        ref.addListenerForSingleValueEvent(new ValueEventListener() {
            @Override
            public void onDataChange(DataSnapshot snapshot) {
                result[0] = snapshot.getValue(String.class);
                latch.countDown();
            }

            @Override
            public void onCancelled(DatabaseError error) {
                result[0] = "DefaultPlayer";
                latch.countDown();
            }
        });
        try {
            latch.await();
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            return "DefaultPlayer";
        }
        return result[0] != null ? result[0] : "DefaultPlayer";
    }

    // Método adicional para pruebas con WireMock (no está en la interfaz)
    public boolean patchMultiPath(String path, Map<String, Object> updates) throws IOException {
        // TODO: Implementar llamada HTTP real con OkHttp
        return true;
    }
}

